import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

gelu_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void gelu_kernel_vec4(const float4* __restrict__ x, float4* __restrict__ y, int n4) {
    const float c = 0.7978845608028654f; // sqrt(2/pi)
    const float a = 0.044715f;
    int base = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = blockDim.x * gridDim.x;
    // Process 2 float4 vectors (8 floats) per loop iteration to increase
    // memory-level parallelism and better hide global memory latency.
    for (int idx = base; idx < n4; idx += stride * 2) {
        float4 v0 = x[idx];
        float x00 = v0.x, x01 = v0.y, x02 = v0.z, x03 = v0.w;
        float t00 = c * (x00 + a * x00 * x00 * x00);
        float t01 = c * (x01 + a * x01 * x01 * x01);
        float t02 = c * (x02 + a * x02 * x02 * x02);
        float t03 = c * (x03 + a * x03 * x03 * x03);
        v0.x = 0.5f * x00 * (1.0f + tanhf(t00));
        v0.y = 0.5f * x01 * (1.0f + tanhf(t01));
        v0.z = 0.5f * x02 * (1.0f + tanhf(t02));
        v0.w = 0.5f * x03 * (1.0f + tanhf(t03));
        y[idx] = v0;
        int idx2 = idx + stride;
        if (idx2 < n4) {
            float4 v1 = x[idx2];
            float x10 = v1.x, x11 = v1.y, x12 = v1.z, x13 = v1.w;
            float t10 = c * (x10 + a * x10 * x10 * x10);
            float t11 = c * (x11 + a * x11 * x11 * x11);
            float t12 = c * (x12 + a * x12 * x12 * x12);
            float t13 = c * (x13 + a * x13 * x13 * x13);
            v1.x = 0.5f * x10 * (1.0f + tanhf(t10));
            v1.y = 0.5f * x11 * (1.0f + tanhf(t11));
            v1.z = 0.5f * x12 * (1.0f + tanhf(t12));
            v1.w = 0.5f * x13 * (1.0f + tanhf(t13));
            y[idx2] = v1;
        }
    }
}
__global__ void gelu_kernel_scalar(const float* __restrict__ x, float* __restrict__ y, int n, int offset) {
    const float c = 0.7978845608028654f;
    const float a = 0.044715f;
    for (int idx = blockIdx.x * blockDim.x + threadIdx.x + offset;
         idx < n;
         idx += blockDim.x * gridDim.x) {
        float xi = x[idx];
        float t = c * (xi + a * xi * xi * xi);
        y[idx] = 0.5f * xi * (1.0f + tanhf(t));
    }
}
torch::Tensor gelu_cuda(torch::Tensor x) {
    auto y = torch::empty_like(x);
    int n = x.numel();
    int n4 = n / 4;
    int rem_start = n4 * 4;
    int device;
    cudaGetDevice(&device);
    int sm_count = 1;
    cudaDeviceGetAttribute(&sm_count, cudaDevAttrMultiProcessorCount, device);
    if (n4 > 0) {
        const int threads = 256;
        int blocks_needed = (n4 + threads - 1) / threads;
        int blocks_persistent = sm_count * 32; // saturate SMs; grid-stride loop covers remainder
        int blocks = blocks_needed < blocks_persistent ? blocks_needed : blocks_persistent;
        if (blocks < 1) blocks = 1;
        gelu_kernel_vec4<<<blocks, threads>>>(
            reinterpret_cast<const float4*>(x.data_ptr<float>()),
            reinterpret_cast<float4*>(y.data_ptr<float>()),
            n4
        );
    }
    int rem = n - rem_start;
    if (rem > 0) {
        const int threads = 256;
        int blocks_needed = (rem + threads - 1) / threads;
        int blocks_persistent = sm_count * 32;
        int blocks = blocks_needed < blocks_persistent ? blocks_needed : blocks_persistent;
        if (blocks < 1) blocks = 1;
        gelu_kernel_scalar<<<blocks, threads>>>(
            x.data_ptr<float>(),
            y.data_ptr<float>(),
            n,
            rem_start
        );
    }
    return y;
}
"""

gelu_cpp_source = "torch::Tensor gelu_cuda(torch::Tensor x);"

gelu_module = load_inline(
    name="gelu_module",
    cpp_sources=gelu_cpp_source,
    cuda_sources=gelu_source,
    functions=["gelu_cuda"],
    extra_cuda_cflags=["-use_fast_math"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()
        self.gelu = gelu_module

    def forward(self, x):
        x = x.contiguous()
        return self.gelu.gelu_cuda(x)


